async function fetchFresh(p) {                       // bypass the 10-minute HTTP cache so a new deploy is picked up
  const r = await fetch(new URL(p, SCOPE).href, { cache: "no-cache" });
  if (!r.ok) throw new Error(r.status + " " + p);
  return r;
}
async function store(p, res) { const c = await caches.open(FILES); await c.put(keyOf(p), res); }

self.addEventListener("install", e => {
  e.waitUntil((async () => {
    const c = await caches.open(FILES);
    await Promise.all(SHELL.filter(p => REV[p]).map(async p => {
      if (await c.match(keyOf(p))) return;
      try { await c.put(keyOf(p), await fetchFresh(p)); } catch (err) {}
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", e => {
  e.waitUntil((async () => {
    for (const name of await caches.keys()) if (name !== FILES && name !== FONTS) await caches.delete(name);
    const c = await caches.open(FILES);
    for (const req of await c.keys()) {                // drop files whose content changed or that were removed
      const u = new URL(req.url), p = rel(u);
      if (!REV[p] || u.searchParams.get("rev") !== REV[p]) await c.delete(req);
    }
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", e => {
  const req = e.request; if (req.method !== "GET") return;
  const url = new URL(req.url);

  /* Google Fonts: CSS refreshed in the background, font files kept */
  if (url.hostname === "fonts.googleapis.com" || url.hostname === "fonts.gstatic.com") {
    e.respondWith((async () => {
      const c = await caches.open(FONTS), hit = await c.match(req);
      const net = fetch(req).then(r => { if (r.ok || r.type === "opaque") c.put(req, r.clone()); return r; }).catch(() => hit);
      return url.hostname === "fonts.gstatic.com" ? (hit || net) : (hit ? (e.waitUntil(net), hit) : net);
    })());
    return;
  }
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  let p = rel(url); if (p === "") p = "index.html";

  /* pages: network first — but when a saved copy exists and the network is slow (weak mobile data),
     show the saved copy after 3 s instead of a blank screen; the network answer still refreshes the cache */
  if (req.mode === "navigate" || p.endsWith(".html")) {
    const net = fetch(req);
    e.waitUntil(net.then(r => { if (r.ok && REV[p]) return store(p, r.clone()); }).catch(() => {}));
    e.respondWith((async () => {
      const c = await caches.open(FILES);
      const saved = (REV[p] && await c.match(keyOf(p))) || await c.match(req, { ignoreSearch: true });
      try {
        if (!saved) return await net;
        return await Promise.race([net, new Promise(res => setTimeout(() => res(saved), 3000))]);
      } catch (err) {
        return saved || await c.match(keyOf("offline.html")) || Response.error();
      }
    })());
    return;
  }

  /* everything published: cache first */
  if (REV[p]) {
    e.respondWith((async () => {
      const c = await caches.open(FILES), hit = await c.match(keyOf(p));
      if (hit) return hit;
      try { const r = await fetchFresh(p); e.waitUntil(c.put(keyOf(p), r.clone())); return r; }
      catch (err) { return fetch(req); }
    })());
    return;
  }

  /* images that were never published (e.g. optional chapter pictures) — answer 404 without a network trip */
  if (p.startsWith("img/")) { e.respondWith(new Response("", { status: 404 })); return; }
});
